package observe

import (
	"bytes"
	"encoding/json"
	"fmt"
	"sync"
)

// Snapshot is an immutable observation payload with a local monotonic version.
// State must be canonical JSON generated by the visual state estimator. A phase
// label alone does not establish turn eligibility or permission to send input.
type Snapshot struct {
	Version uint64
	Source  string
	Phase   string
	State   json.RawMessage
}

// Intent binds an opaque action request to the exact observed version. The
// execution adapter must interpret and validate Action against that snapshot.
type Intent struct {
	ID      string
	Version uint64
	Action  json.RawMessage
}

type Lifecycle struct {
	mu      sync.Mutex
	current Snapshot
	pending *Intent
	used    map[string]bool
}

// Publish replaces the observation and reports whether its semantic state
// changed. Fresh evidence with unchanged state updates Source without waking
// the strategy. The owner remains responsible for observation freshness.
func (l *Lifecycle) Publish(source, phase string, state json.RawMessage) (Snapshot, bool, error) {
	if source == "" || phase == "" || !json.Valid(state) {
		return Snapshot{}, false, fmt.Errorf("source, phase and JSON state required")
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	changed := l.current.Version == 0 || l.current.Phase != phase || !bytes.Equal(l.current.State, state)
	if changed {
		l.current.Version++
	}
	l.current.Source, l.current.Phase = source, phase
	l.current.State = append(json.RawMessage(nil), state...)
	return copySnapshot(l.current), changed, nil
}

func copySnapshot(s Snapshot) Snapshot {
	s.State = append(json.RawMessage(nil), s.State...)
	return s
}

// Begin claims an action before delivery. The claim survives delivery failure;
// callers must reconcile an uncertain action instead of replaying it.
// Restore resumes an already persisted lifecycle without selecting or sending.
func (l *Lifecycle) Restore(snapshot Snapshot, pending *Intent) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.current.Version != 0 || snapshot.Version == 0 || snapshot.Source == "" || !json.Valid(snapshot.State) {
		return fmt.Errorf("invalid lifecycle restore")
	}
	l.current = copySnapshot(snapshot)
	l.used = map[string]bool{}
	if pending != nil {
		if pending.Version != snapshot.Version || pending.ID == "" || !json.Valid(pending.Action) {
			return fmt.Errorf("invalid restored intent")
		}
		copyIntent := *pending
		copyIntent.Action = append(json.RawMessage(nil), pending.Action...)
		l.pending = &copyIntent
		l.used[pending.ID] = true
	}
	return nil
}

func (l *Lifecycle) Begin(intent Intent) (Snapshot, error) {
	if intent.ID == "" || !json.Valid(intent.Action) {
		return Snapshot{}, fmt.Errorf("action ID and JSON action required")
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.pending != nil || intent.Version == 0 || intent.Version != l.current.Version || l.used[intent.ID] {
		return Snapshot{}, fmt.Errorf("pending, stale or duplicate action")
	}
	if l.used == nil {
		l.used = make(map[string]bool)
	}
	intent.Action = append(json.RawMessage(nil), intent.Action...)
	l.used[intent.ID] = true
	l.pending = &intent
	return copySnapshot(l.current), nil
}

// Confirm releases a claim only after the caller independently verifies the
// action-specific postcondition against a newer published observation. A
// transport success or phase label alone is not a semantic postcondition.
func (l *Lifecycle) Confirm(id string, version uint64, verified bool) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if !verified || l.pending == nil || id != l.pending.ID || version != l.current.Version || version <= l.pending.Version {
		return fmt.Errorf("action outcome not confirmed by current newer state")
	}
	l.pending = nil
	return nil
}
